module.exports = "<ng-template #detailContent>\n  <section class=\"bmb_grades-modal\">\n    @for (partial of partials; track $index) {\n      <section\n        bmbLayout\n        margin=\"none\"\n        justify=\"spaceBetween\"\n        [dynamicCols]=\"true\"\n      >\n        <h2 class=\"bmb_grades-modal-title\" bmbLayoutItem>\n          {{ partial.title }}\n        </h2>\n        <bmb-grade-value\n          [score]=\"partial.score\"\n          type=\"partial-grade\"\n          bmbLayoutItem\n        />\n      </section>\n      @if ($index < partials.length - 1) {\n        <bmb-divider [type]=\"'simple'\" />\n      }\n    }\n  </section>\n</ng-template>\n\n<section class=\"bmb_grades\">\n  @if (isMicro()) {\n    <bmb-container appearance=\"primary-home\" class=\"bmb_grades-micro\">\n      <bmb-title-content\n        [componentTitle]=\"gradeTitle()!\"\n        titleSize=\"4\"\n        titleFontWeight=\"500\"\n        [isCenterContent]=\"true\"\n      />\n      <bmb-title-content\n        [componentTitle]=\"componentTitle() || title()\"\n        titleSize=\"4\"\n        titleFontWeight=\"400\"\n        [isCenterContent]=\"true\"\n      />\n      <bmb-academic-progress\n        [accredited]=\"accredited()!\"\n        [average]=\"average()!\"\n        [summary]=\"summary()!\"\n      />\n    </bmb-container>\n  } @else {\n    <bmb-inner-header\n      [componentTitle]=\"getGradesTitle()\"\n      [showClose]=\"true\"\n      [trailingIconSecondary]=\"getCalendarIcon()\"\n      (onHandleBack)=\"handleLeftGradesClick($event)\"\n      (onHandleTrailingSecondary)=\"handleRightGradesClick()\"\n    >\n      <bmb-chevron-title-selector\n        [componentTitle]=\"getTitle()\"\n        leadingIcon=\"chevron_left\"\n        trailingIcon=\"chevron_right\"\n        (onLeadingClick)=\"handleLeftPeriodClick()\"\n        (onTrailingClick)=\"handleRightPeriodClick()\"\n      />\n      @if (showPrincipalDetail) {\n        <bmb-academic-progress\n          [accredited]=\"{\n            name: 'Materias Acreditadas',\n            value: getAccreditedClasses()\n          }\"\n          [average]=\"{ name: 'Promedio Semestre', value: getPeriodAverage() }\"\n          [summary]=\"{ name: 'Horas Servicio', value: getServiceHours() }\"\n        />\n      }\n    </bmb-inner-header>\n    <section class=\"bmb_grades-content\">\n      @for (element of getElements(); track $index) {\n        <bmb-container-button\n          [title]=\"getDetailTitle(element)\"\n          [subtitle]=\"getDetailSubtitle(element)\"\n          [score]=\"getDetailScore(element)\"\n          iconLeft=\"chevron_left\"\n          iconRight=\"chevron_right\"\n          (onButton)=\"handleDetails(element)\"\n        />\n      }\n    </section>\n  }\n</section>\n";

